<?php
declare(strict_types=1);
const BACKUP_MAX_BYTES=20*1024*1024;
const BACKUP_TABLES=['customers','products','leads','tasks','documents','document_items','payments','expenses','business_settings'];
function backup_key(): string { global $config;$key=hex2bin($config['key']);if($key===false||strlen($key)!==32)throw new DomainException('A valid application encryption key is required.');return $key; }
function backup_data(): array {
    // A caller-owned transaction retains its existing snapshot and ownership.
    // Standalone backups explicitly use repeatable reads, even if the server defaults differ.
    if(!db()->inTransaction())db()->exec('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');
    return transaction(function(): array {
        $business=one('SELECT name,profile,demo_mode FROM businesses WHERE id=?',[bid()]);
        $data=[];
        foreach(BACKUP_TABLES as $table){
            $data[$table]=$table==='document_items'
                ?rows('SELECT i.* FROM document_items i JOIN documents d ON d.id=i.document_id WHERE d.business_id=?',[bid()])
                :rows("SELECT * FROM $table WHERE business_id=?",[bid()]);
        }
        return ['version'=>'1.0.0','business_id'=>bid(),'created_at'=>date(DATE_ATOM),'business'=>$business,'tables'=>$data];
    });
}
function create_backup(): int { require_permission('backup.create');global $config;$data=json_encode(backup_data(),JSON_THROW_ON_ERROR);$envelope=json_encode(['payload'=>base64_encode($data),'signature'=>hash_hmac('sha256',$data,backup_key())],JSON_THROW_ON_ERROR);if(strlen($envelope)>BACKUP_MAX_BYTES)throw new DomainException('Backup exceeds the 20 MB limit.');if(!is_dir($config['storage'].'/backups'))mkdir($config['storage'].'/backups',0700,true);$name=bin2hex(random_bytes(24)).'.json';$path=$config['storage'].'/backups/'.$name;if(file_put_contents($path,$envelope,LOCK_EX)===false)throw new DomainException('Backup could not be written.');chmod($path,0600);query('INSERT INTO backup_records(business_id,filename,checksum,bytes) VALUES(?,?,?,?)',[bid(),$name,hash('sha256',$envelope),strlen($envelope)]);$id=(int)db()->lastInsertId();audit('backup.created','backup',$id,['bytes'=>strlen($envelope)]);return $id; }
function read_backup(string $raw): array { if(strlen($raw)>BACKUP_MAX_BYTES)throw new DomainException('Backup exceeds the 20 MB limit.');try{$env=json_decode($raw,true,32,JSON_THROW_ON_ERROR);$payload=base64_decode($env['payload']??'',true);if(!is_string($payload)||!hash_equals(hash_hmac('sha256',$payload,backup_key()),(string)($env['signature']??'')))throw new DomainException('Backup integrity check failed. Use a backup from this installation.');$data=json_decode($payload,true,64,JSON_THROW_ON_ERROR);}catch(JsonException|TypeError $e){throw new DomainException('Invalid backup file.');}if(($data['version']??'')!=='1.0.0'||(int)($data['business_id']??0)!==bid()||array_keys($data['tables']??[])!==BACKUP_TABLES)throw new DomainException('This backup is not compatible with this business or schema version.');foreach($data['tables'] as $table=>$records){if(!is_array($records)||count($records)>100000)throw new DomainException('Backup resource limit exceeded.');foreach($records as $r)if($table!=='document_items'&&(int)($r['business_id']??0)!==bid())throw new DomainException('Backup contains a record from another business.');}return $data; }
function restore_backup(array $data): void { require_owner();$recovery=create_backup();transaction(function()use($data,$recovery){query('SELECT id FROM businesses WHERE id=? FOR UPDATE',[bid()]);foreach(array_reverse(BACKUP_TABLES) as $table){if($table==='document_items')query('DELETE i FROM document_items i JOIN documents d ON d.id=i.document_id WHERE d.business_id=?',[bid()]);elseif($table==='documents'){query('UPDATE documents SET source_id=NULL WHERE business_id=?',[bid()]);query('DELETE FROM documents WHERE business_id=?',[bid()]);}else query("DELETE FROM $table WHERE business_id=?",[bid()]);}
foreach(BACKUP_TABLES as $table){$columns=array_column(rows("SHOW COLUMNS FROM $table"),'Field');$source=[];foreach($data['tables'][$table] as $r){if(array_diff(array_keys($r),$columns)||array_diff($columns,array_keys($r)))throw new DomainException('Backup columns do not match the installed schema.');if($table==='documents'&&!empty($r['source_id'])){$source[]=[(int)$r['id'],(int)$r['source_id']];$r['source_id']=null;}$names=implode(',',array_map(fn($k)=>'`'.$k.'`',array_keys($r)));$marks=implode(',',array_fill(0,count($r),'?'));query("INSERT INTO $table ($names) VALUES($marks)",array_values($r));}foreach($source as [$id,$sid])query('UPDATE documents SET source_id=? WHERE id=? AND business_id=?',[$sid,$id,bid()]);}
query('UPDATE businesses SET name=?,profile=?,demo_mode=? WHERE id=?',[$data['business']['name'],$data['business']['profile'],$data['business']['demo_mode'],bid()]);validate_financial_integrity();audit('backup.restored','backup',$recovery,['source_date'=>$data['created_at']]);}); }
function validate_financial_integrity(): void { $bad=(int)scalar("SELECT COUNT(*) FROM documents d LEFT JOIN (SELECT document_id,SUM(subtotal) subtotal,SUM(discount_total) discount_total,SUM(tax_total) tax_total,SUM(total) total FROM document_items GROUP BY document_id) i ON i.document_id=d.id WHERE d.business_id=? AND (i.document_id IS NULL OR d.subtotal<>i.subtotal OR d.discount_total<>i.discount_total OR d.tax_total<>i.tax_total OR d.total<>i.total)",[bid()]);$bad+=(int)scalar("SELECT COUNT(*) FROM (SELECT d.id,d.total,SUM(p.amount) paid FROM documents d JOIN payments p ON p.document_id=d.id AND p.business_id=d.business_id AND p.reversed_at IS NULL WHERE d.business_id=? GROUP BY d.id HAVING paid>total) q",[bid()]);if($bad)throw new DomainException('Financial integrity validation failed. Changes have been rolled back.'); }
function demo_preview(): array { $counts=[];foreach(['customers','products','leads','tasks','documents','payments','expenses'] as $table)$counts[$table]=(int)scalar("SELECT COUNT(*) FROM $table WHERE business_id=? AND is_demo=1",[bid()]);return $counts; }
function remove_demo(): void { require_owner();create_backup();transaction(function(){query('SELECT id FROM businesses WHERE id=? FOR UPDATE',[bid()]);
$dependent=(int)scalar('SELECT COUNT(*) FROM documents d JOIN customers c ON c.id=d.customer_id WHERE d.business_id=? AND d.is_demo=0 AND c.is_demo=1',[bid()]);
$dependent+=(int)scalar('SELECT COUNT(*) FROM payments p JOIN documents d ON d.id=p.document_id WHERE p.business_id=? AND p.is_demo=0 AND d.is_demo=1',[bid()]);
$dependent+=(int)scalar('SELECT COUNT(*) FROM document_items i JOIN documents d ON d.id=i.document_id JOIN products p ON p.id=i.product_id WHERE d.business_id=? AND d.is_demo=0 AND p.is_demo=1',[bid()]);
foreach(['tasks','leads'] as $t)$dependent+=(int)scalar("SELECT COUNT(*) FROM $t r JOIN customers c ON c.id=r.customer_id WHERE r.business_id=? AND r.is_demo=0 AND c.is_demo=1",[bid()]);
$dependent+=(int)scalar('SELECT COUNT(*) FROM documents d JOIN documents s ON s.id=d.source_id WHERE d.business_id=? AND d.is_demo=0 AND s.is_demo=1',[bid()]);
if($dependent)throw new DomainException('Real records depend on demo data. Keep the demo workspace or replace those links before removal.');
query('DELETE FROM payments WHERE business_id=? AND is_demo=1',[bid()]);query('DELETE i FROM document_items i JOIN documents d ON d.id=i.document_id WHERE d.business_id=? AND d.is_demo=1',[bid()]);query('UPDATE documents SET source_id=NULL WHERE business_id=? AND is_demo=1',[bid()]);query('DELETE FROM documents WHERE business_id=? AND is_demo=1',[bid()]);foreach(['tasks','leads','expenses','products','customers'] as $table)query("DELETE FROM $table WHERE business_id=? AND is_demo=1",[bid()]);query("UPDATE users SET active=0 WHERE business_id=? AND is_demo=1 AND role='manager'",[bid()]);query('UPDATE businesses SET demo_mode=0 WHERE id=?',[bid()]);audit('demo.removed','business',bid());}); }
